func mailSortLabel(filters models.EmailFilters) string {
	switch filters.SortBy {
	case "sender":
		return "Sender"
	case "subject":
		return "Subject"
	case "size":
		return "Size"
	case "unread":
		return "Unread first"
	case "starred":
		return "Starred first"
	case "attachments":
		return "Attachments first"
	default:
		return "Date"
	}
}

